import { computed, mount, selector, signal } from 'kerfjs';
import { Combobox } from '@kerfjs/ui/combobox';
import { wireComboboxes } from '@kerfjs/ui/wire-comboboxes';

type Source = 'incoming' | 'outgoing';
type RecordItem = { id: number; label: string };
let nextPickerId = 0;

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: 'row') => void,
) {
  const counts = { incoming: signal(4), outgoing: signal(7) };
  const active = signal<Source>('incoming');
  const badge = computed(() => `${counts[active.value].value} crates`);
  const selectedId = signal<number | null>(null);
  const isSelected = selector(selectedId);
  const pickerId = `study-fruit-${++nextPickerId}`;
  const suggestions = ['Apricot', 'Blueberry', 'Cherry'];

  const doc = root.ownerDocument;
  const app = doc.createElement('div');
  const inspector = doc.createElement('div');
  const rows = doc.createElement('div');
  app.append(inspector, rows);
  root.append(app);

  const stopInspector = mount(inspector, () => (
    <>
      <output data-badge="" title={badge}>{badge}</output>
      <input data-note="" />
    </>
  ));

  function mountRow(record: RecordItem) {
    const host = doc.createElement('div');
    rows.append(host);
    const label = signal(record.label);
    const selected = isSelected(record.id);
    const ariaSelected = computed(() => selected.value ? 'true' : 'false');
    const stop = mount(host, () => {
      mark('row');
      return (
        <div data-key={record.id} data-row={record.id} aria-selected={ariaSelected}>
          <span>{label}</span>
          <input />
        </div>
      );
    });
    return { host, label, stop };
  }

  const mountedRows = new Map<number, ReturnType<typeof mountRow>>();
  let records: RecordItem[] = [];
  let disposed = false;
  let stopPicker: (() => void) | undefined;

  function replaceRecords(next: RecordItem[]) {
    const focused = doc.activeElement;
    const editor = focused instanceof HTMLInputElement && rows.contains(focused)
      ? focused
      : null;
    const start = editor?.selectionStart;
    const end = editor?.selectionEnd;
    const direction = editor?.selectionDirection;

    const nextIds = new Set(next.map(record => record.id));
    for (const [id, row] of mountedRows) {
      if (nextIds.has(id)) continue;
      row.stop();
      row.host.remove();
      mountedRows.delete(id);
    }

    let position = rows.firstElementChild;
    for (const record of next) {
      let row = mountedRows.get(record.id);
      if (row) {
        row.label.value = record.label;
      } else {
        row = mountRow(record);
        mountedRows.set(record.id, row);
      }
      if (row.host !== position) rows.insertBefore(row.host, position);
      position = row.host.nextElementSibling;
    }
    records = next;

    if (editor && rows.contains(editor) && doc.activeElement !== editor) {
      editor.focus({ preventScroll: true });
      if (typeof start === 'number' && typeof end === 'number') {
        editor.setSelectionRange(start, end, direction ?? undefined);
      }
    }
  }

  replaceRecords([
    { id: 1, label: 'One' },
    { id: 2, label: 'Two' },
    { id: 3, label: 'Three' },
    { id: 4, label: 'Four' },
  ]);

  function close() {
    const stop = stopPicker;
    stopPicker = undefined;
    stop?.();
  }

  return {
    count(source: Source, value: number) {
      if (!disposed) counts[source].value = value;
    },
    mode(source: Source) {
      if (!disposed) active.value = source;
    },
    select(id: number) {
      if (!disposed) selectedId.value = id;
    },
    refetch(next: RecordItem[]) {
      if (!disposed) replaceRecords(next.map(({ id, label }) => ({ id, label })));
    },
    swap() {
      if (disposed || records.length < 2) return;
      const next = records.slice();
      [next[0], next[1]] = [next[1], next[0]];
      replaceRecords(next);
    },
    open() {
      if (disposed || stopPicker) return;
      const host = doc.createElement('div');
      app.append(host);
      const unmount = mount(host, () => (
        <Combobox
          id={pickerId}
          label="Fruit"
          suggestions={suggestions}
          createLabel={false}
        />
      ));
      let live = true;
      const unwire = wireComboboxes(host, {
        onCommit: ({ value }) => {
          if (live) onCommit(value);
        },
      });
      stopPicker = () => {
        live = false;
        unwire();
        unmount();
        host.remove();
      };
    },
    close,
    dispose() {
      if (disposed) return;
      disposed = true;
      close();
      for (const row of mountedRows.values()) row.stop();
      mountedRows.clear();
      records = [];
      stopInspector();
      app.remove();
    },
  };
}
